import{_ as l,H as o,f as t,i as a}from"./chunks/framework.DLd0CbzH.js";const p=JSON.parse('{"title":"Архитектура","description":"","frontmatter":{},"headers":[],"relativePath":"dev/architecture.md","filePath":"dev/architecture.md"}'),r={name:"dev/architecture.md"};function c(i,e,d,n,s,u){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="архитектура" tabindex="-1">Архитектура <a class="header-anchor" href="#архитектура" aria-label="Permalink to &quot;Архитектура&quot;">​</a></h1><blockquote><p><strong>Каноничный источник:</strong> <code>docs/03_Dev/Architecture.md</code>. Этот файл — краткая версия для AI-навигации, имена моделей/таблиц сверены с кодом 2026-06-14.</p></blockquote><p>Этот раздел — адаптированная версия старого <code>docs/architecture.md</code>.</p><h2 id="архитектура-системы-сбора-данных" tabindex="-1">Архитектура системы сбора данных <a class="header-anchor" href="#архитектура-системы-сбора-данных" aria-label="Permalink to &quot;Архитектура системы сбора данных&quot;">​</a></h2><p>Система построена на модульной архитектуре с четким разделением ответственности между общим ядром (Platform) и специфичными реализациями площадок (Eis, B2B и т.д.).</p><h2 id="терминология" tabindex="-1">Терминология <a class="header-anchor" href="#терминология" aria-label="Permalink to &quot;Терминология&quot;">​</a></h2><ol><li><strong>Platform (Платформа)</strong> — объект, описывающий источник данных (например, ЕИС).</li><li><strong>Crawler (Профиль/Настройка)</strong> — модель <code>App\\Models\\Crawler\\Crawler</code>. Содержит параметры поиска: фильтры, регионы, частоту обновлений. <ul><li>Таблица: <code>plt_crawlers</code></li></ul></li><li><strong>Link (Результат обхода)</strong> — модель <code>App\\Models\\Crawler\\Link</code>. Конкретная найденная закупка/лот на первом этапе. <ul><li>Таблица: <code>plt_crawler_links</code></li></ul></li><li><strong>LinkAttachment (Документ-вложение)</strong> — модель <code>App\\Models\\Crawler\\LinkAttachment</code>. Файл, найденный внутри Link (смета, ТЗ, контракт). <ul><li>Таблица: <code>plt_crawler_link_attachments</code></li></ul></li><li><strong>DocumentAnalysis (Сессия AI-анализа)</strong> — модель <code>App\\Models\\DocumentAnalysis\\DocumentAnalysis</code>. Полиморфно привязана к вложению; несёт статус AI-пайплайна (enum <code>AnalysisStatus</code>). <ul><li>Таблица: <code>plt_document_analysis</code></li></ul></li></ol><h2 id="схема-работы-в-общих-чертах" tabindex="-1">Схема работы (в общих чертах) <a class="header-anchor" href="#схема-работы-в-общих-чертах" aria-label="Permalink to &quot;Схема работы (в общих чертах)&quot;">​</a></h2><ol><li><strong>Crawling (обход)</strong><ul><li>Сервис <code>AbstractCrawlingService</code> запускается для конкретного <code>Crawler</code>.</li><li>Находит новые объекты на источнике.</li><li>Формирует <code>LinkDto</code> и сохраняет в <code>plt_crawler_links</code> со статусом <code>pending</code>.</li></ul></li><li><strong>Parsing (анализ и разбор)</strong><ul><li>Воркер берет ссылки из <code>plt_crawler_links</code>.</li><li>Собирает список документов-вложений в <code>plt_crawler_link_attachments</code>.</li><li>Создаёт сессию <code>DocumentAnalysis</code> и через AI (Gemini) классифицирует: является ли документ сметой.</li><li>Если да — извлекает позиции сметы в <code>plt_document_analysis_responses</code> (нормализация в <code>ord_*</code> — Стадия 5, не подключена).</li></ul></li></ol>',9)])])}const h=l(r,[["render",c]]);export{p as __pageData,h as default};
